#!/bin/bash
# Example podman commands generated by ContainerCommandGenerator
# These are reference examples showing the structure of generated commands

# Example 1: Single GPU vLLM deployment
# Model: qwen2.5-7b-instruct-awq
# GPUs: [0]
# Port: 8001
podman run -d --rm \
  --name vllm-qwen2-5-7b-instruct-awq-a1b2c3d4 \
  --device nvidia.com/gpu=0 \
  -v /data/projects/ai/models:/models:ro \
  --shm-size 16g \
  -p 8001:8000 \
  -e CUDA_VISIBLE_DEVICES=0 \
  --label llm-serve=true \
  --label model=qwen2.5-7b-instruct-awq \
  --label runtime=vllm \
  --label gpus=[0] \
  vllm/vllm-openai:latest \
  --model /models/qwen2.5-7b-instruct-awq \
  --max-model-len 8192 \
  --max-num-seqs 4


