  --tensor-parallel-size 2 \
  --max-num-seqs 4


# Example 3: vLLM with custom environment variables
# Model: llama-3.1-70b-instruct-fp16
# GPUs: [2, 3, 4, 5]
# Port: 8003
# With HuggingFace token
podman run -d --rm \
  --name vllm-llama-3-1-70b-instruct-fp16-c3d4e5f6 \
  --device nvidia.com/gpu=2 \
  --device nvidia.com/gpu=3 \
  --device nvidia.com/gpu=4 \
  --device nvidia.com/gpu=5 \
  -v /data/projects/ai/models:/models:ro \
  --shm-size 16g \
  -p 8003:8000 \
  -e CUDA_VISIBLE_DEVICES=2,3,4,5 \
  -e HF_TOKEN=hf_yourtoken \
  -e TRANSFORMERS_CACHE=/models/.cache \
  --label llm-serve=true \
  --label model=llama-3.1-70b-instruct-fp16 \
  --label runtime=vllm \
  --label gpus=[2,3,4,5] \
  vllm/vllm-openai:latest \
  --model /models/llama-3.1-70b-instruct-fp16 \
  --max-model-len 32768 \
  --tensor-parallel-size 4 \
  --max-num-seqs 8


